export default function StylebookPage() {
  const containerRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const handleClick = (e) => {
      const link = e.target.closest('a');
      if (link && link.href) {
        try {
          const url = new URL(link.href, window.location.origin);
          if (url.origin === window.location.origin && !url.pathname.startsWith('/jpg') && !url.pathname.startsWith('/png') && !url.pathname.startsWith('/svg')) {
            e.preventDefault();
            navigate(url.pathname);
            window.scrollTo(0, 0);
          }
        } catch (err) {}
      }
    };

    el.addEventListener('click', handleClick);
    return () => el.removeEventListener('click', handleClick);
  }, [navigate]);

  return <div ref={containerRef} dangerouslySetInnerHTML={{ __html: rawHtml }} />;
}
